"""eval_dqc.py — Score the DQC Q function on single-step zarr data.

Run in the `simpler_env` conda env (JAX). The DQC Q takes (image, action, text):
  * image  — agentview_image from the zarr, one frame per env step
  * action — the executed 7-D action at that step (single-step VLA, no chunks)
  * text   — a 512-d MUSE (USE-4) embedding of the instruction; generated by
             get_muse_emb.py. This script auto-generates it (in a subprocess so
             TensorFlow never shares this JAX process) if --text-emb-file is
             missing.

The zarr is the clean single-step source: actions are flat (T, 7), images flat
(T, H, W, 3), episodes split by `dones`, success = terminal `rewards` > 0.

It also writes a self-contained `pairs.npz` (images + actions + labels for the
sampled steps) so eval_robomonkey.py — which runs in a different env without
zarr — scores the *identical* (image, action) pairs.

Usage
-----
conda run -n simpler_env python eval_dqc.py \
    --zarr-path /home/harine/data/eggplant_in_basket/all_data/state0.zarr \
    --instruction "put the eggplant in the basket" \
    --out-dir results/dqc_vs_verifier --max-eps-per-class 40 --stride 4
"""
from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path

import numpy as np

from eval_q import build_scorer, make_plot  # reused DQC forward pass + plot

_HERE = Path(__file__).resolve().parent


def sample_pairs(zarr_path, max_per_class, stride, seed):
    """Balanced success/failure episode sample, strided over steps.

    Returns images + raw actions + labels for every selected step.
    """
    import zarr
    z = zarr.open(zarr_path, "r")
    obs = z["data"]["obs"]
    if "agentview_image" not in list(obs.keys()):
        raise ValueError(
            f"{zarr_path} has no agentview_image (keys: {list(obs.keys())}). "
            "This shard is state-only (e.g. carrot) — the DQC Q needs images.")

    dones, rewards = z["data"]["dones"][:], z["data"]["rewards"][:]
    ep_ends = np.where(dones)[0]
    ep_starts = np.concatenate([[0], ep_ends[:-1] + 1])
    success = rewards[ep_ends] > 0

    n_s, n_f = int(success.sum()), int((~success).sum())
    print(f"[sample] {len(ep_ends)} eps — {n_s} success, {n_f} failure")
    rng = np.random.default_rng(seed)
    sel_s = rng.choice(np.where( success)[0], min(max_per_class, n_s), replace=False)
    sel_f = rng.choice(np.where(~success)[0], min(max_per_class, n_f), replace=False)
    eps = np.sort(np.concatenate([sel_s, sel_f]))
    print(f"[sample] {len(sel_s)} success + {len(sel_f)} failure eps, stride={stride}")

    g_index, ep_idx, t_real, succ = [], [], [], []
    for e in eps:
        s, en = int(ep_starts[e]), int(ep_ends[e]) + 1
        for g in range(s, en, stride):
            g_index.append(g); ep_idx.append(int(e))
            t_real.append(g - s); succ.append(bool(success[e]))
    g_index = np.asarray(g_index)

    print(f"[sample] reading {len(g_index)} (image, action) pairs ...")
    images  = np.stack([np.asarray(obs["agentview_image"][g]) for g in g_index]).astype(np.uint8)
    actions = np.stack([np.asarray(z["data"]["actions"][g]) for g in g_index]).astype(np.float32)
    return dict(g_index=g_index, ep_idx=np.asarray(ep_idx), t_real=np.asarray(t_real),
                success=np.asarray(succ), images=images, actions=actions)


def ensure_muse(instruction, text_emb_file):
    """Generate the MUSE embedding via get_muse_emb.py (subprocess) if missing."""
    p = Path(text_emb_file)
    if p.exists():
        print(f"[muse] using existing {p}")
        return np.load(p).astype(np.float32)
    print(f"[muse] generating MUSE embedding for {instruction!r} → {p}")
    subprocess.run([sys.executable, str(_HERE / "get_muse_emb.py"),
                    "--instruction", instruction, "--out", str(p)], check=True)
    return np.load(p).astype(np.float32)


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--zarr-path",
                    default="/home/harine/data/eggplant_in_basket/all_data/state0.zarr")
    ap.add_argument("--out-dir", default="results/dqc_vs_verifier")
    ap.add_argument("--instruction", default="put the eggplant in the basket")
    ap.add_argument("--text-emb-file", default="task_emb.npy")
    ap.add_argument("--ckpt-dir",
                    default="/home/harine/RoboMonkey/dqc_checkpoint/sd000s_137913.0.20260605_163017")
    ap.add_argument("--max-eps-per-class", type=int, default=40)
    ap.add_argument("--stride", type=int, default=4)
    ap.add_argument("--seed", type=int, default=42)
    ap.add_argument("--img-size", type=int, default=128)
    ap.add_argument("--q-batch", type=int, default=64)
    ap.add_argument("--reuse-pairs", action="store_true",
                    help="Load existing pairs.npz instead of resampling the zarr.")
    args = ap.parse_args()

    out = Path(args.out_dir); out.mkdir(parents=True, exist_ok=True)
    pairs_file = out / "pairs.npz"

    if args.reuse_pairs and pairs_file.exists():
        print(f"[pairs] reusing {pairs_file}")
        d = np.load(pairs_file, allow_pickle=False)
        pairs = {k: d[k] for k in d.files}
    else:
        pairs = sample_pairs(args.zarr_path, args.max_eps_per_class, args.stride, args.seed)
        np.savez_compressed(pairs_file, g_index=pairs["g_index"], ep_idx=pairs["ep_idx"],
                            t_real=pairs["t_real"], success=pairs["success"],
                            actions=pairs["actions"], images=pairs["images"],
                            instruction=np.asarray(args.instruction))
        print(f"[pairs] wrote {pairs_file}  ({pairs_file.stat().st_size/1e6:.0f} MB) "
              f"— eval_robomonkey.py reads this")

    text_emb = ensure_muse(args.instruction, args.text_emb_file)
    assert text_emb.shape == (512,), text_emb.shape

    print(f"[dqc] scoring {len(pairs['g_index'])} pairs ...")
    scorer = build_scorer(args.ckpt_dir)
    G, B = len(pairs["g_index"]), args.q_batch
    q = np.zeros(G, np.float32)
    for s in range(0, G, B):
        q[s:s + B] = scorer(pairs["images"][s:s + B], pairs["actions"][s:s + B],
                            text_emb, args.img_size)
        if (s // B) % 10 == 0:
            print(f"  {min(s + B, G)}/{G}", flush=True)

    import pandas as pd
    df = pd.DataFrame({"ep_idx": pairs["ep_idx"], "success": pairs["success"].astype(bool),
                       "branch_t": pairs["t_real"], "q_value": q,
                       "verifier_score": np.nan, "source": "zarr"})
    df.to_csv(out / "dqc_scores.csv", index=False)
    print(f"[dqc] {len(df)} rows → {out/'dqc_scores.csv'}")

    n_s = df.groupby("ep_idx")["success"].first().sum()
    n_f = df["ep_idx"].nunique() - n_s
    make_plot(df, out / "dqc.png",
              f"DQC Q — single-step zarr\n{args.instruction}  |  "
              f"{n_s} success / {n_f} failure eps  |  {G} (s,a) pairs", "zarr")


if __name__ == "__main__":
    main()
